1	"use client";
2	
3	import { useEffect, useState, useTransition, useRef, useCallback } from "react";
4	import {
5	  getWhatsNew,
6	  markAnnouncementSeen,
7	  type WhatsNewEntry,
8	} from "@/lib/actions-announcements";
9	import { renderMarkdown } from "@/lib/blog";
10	import { GameCoverTile } from "@/components/customer/GameCoverTile";
11	import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
12	
13	const FILTERS = [
14	  { value: "", label: "All" },
15	  { value: "GAME", label: "Game Servers" },
16	  { value: "VPS", label: "VPS" },
17	  { value: "HOSTING", label: "Hosting" },
18	  { value: "MAIL", label: "Mail" },
19	];
20	
21	/**
22	 * Full "What's New" feed: all published announcements in a timeline layout.
23	 * Unseen ones get a "New" badge. When an unseen announcement scrolls into
24	 * view (or is present on initial render), it is marked as seen after a short
25	 * delay so the badge lingers long enough to be noticed.
26	 */
27	export function WhatsNew() {
28	  const [entries, setEntries] = useState<WhatsNewEntry[]>([]);
29	  const [filter, setFilter] = useState("");
30	  const [loading, setLoading] = useState(true);
31	  const [, startTransition] = useTransition();
32	
33	  const load = useCallback((serviceFilter: string) => {
34	    setLoading(true);
35	    getWhatsNew(serviceFilter || undefined)
36	      .then(setEntries)
37	      .catch(() => setEntries([]))
38	      .finally(() => setLoading(false));
39	  }, []);
40	
41	  useEffect(() => {
42	    load(filter);
43	  }, [filter, load]);
44	
45	  function handleFilterChange(val: string) {
46	    setFilter(val);
47	  }
48	
49	  /** Mark an announcement as seen (optimistic local update + server write). */
50	  function handleSeen(id: string) {
51	    setEntries((prev) =>
52	      prev.map((e) => (e.id === id ? { ...e, seen: true } : e)),
53	    );
54	    startTransition(async () => {
55	      try {
56	        await markAnnouncementSeen(id);
57	      } catch {
58	        /* best-effort */
59	      }
60	    });
61	  }
62	
63	  return (
64	    <div className="space-y-6">
65	      {/* Filter tabs */}
66	      <div className="flex flex-wrap gap-2">
67	        {FILTERS.map((f) => (
68	          <button
69	            key={f.value}
70	            onClick={() => handleFilterChange(f.value)}
71	            className={`rounded-lg border px-3 py-1.5 text-sm font-medium transition-colors ${
72	              filter === f.value
73	                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
74	                : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-slate-200"
75	            }`}
76	          >
77	            {f.label}
78	          </button>
79	        ))}
80	      </div>
81	
82	      {/* Content */}
83	      {loading ? (
84	        <div className="py-12 text-center text-sm text-slate-500">
85	          Loading...
86	        </div>
87	      ) : entries.length === 0 ? (
88	        <div className="card flex flex-col items-center justify-center py-14 text-center">
89	          <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
90	            <svg
91	              width="28"
92	              height="28"
93	              viewBox="0 0 24 24"
94	              fill="none"
95	              stroke="#8a70fb"
96	              strokeWidth="1.5"
97	            >
98	              <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
99	            </svg>
100	          </div>
101	          <p className="text-sm font-medium text-white">No updates yet</p>
102	          <p className="mt-1 text-sm text-slate-400">
103	            We&apos;ll post here when there&apos;s something new.
104	          </p>
105	        </div>
106	      ) : (
107	        <div className="space-y-4">
108	          {entries.map((entry) => (
109	            <AnnouncementCard
110	              key={entry.id}
111	              entry={entry}
112	              onSeen={handleSeen}
113	            />
114	          ))}
115	        </div>
116	      )}
117	    </div>
118	  );
119	}
120	
121	function AnnouncementCard({
122	  entry,
123	  onSeen,
124	}: {
125	  entry: WhatsNewEntry;
126	  onSeen: (id: string) => void;
127	}) {
128	  const ref = useRef<HTMLDivElement>(null);
129	  const markedRef = useRef(false);
130	
131	  useEffect(() => {
132	    if (entry.seen || markedRef.current) return;
133	    const el = ref.current;
134	    if (!el) return;
135	
136	    const observer = new IntersectionObserver(
137	      ([e]) => {
138	        if (e.isIntersecting && !markedRef.current) {
139	          markedRef.current = true;
140	          // Short delay so the "New" badge is visible before it disappears.
141	          const timer = setTimeout(() => onSeen(entry.id), 2000);
142	          observer.disconnect();
143	          return () => clearTimeout(timer);
144	        }
145	      },
146	      { threshold: 0.5 },
147	    );
148	    observer.observe(el);
149	    return () => observer.disconnect();
150	  }, [entry.id, entry.seen, onSeen]);
151	
152	  const date = new Date(entry.publishedAt);
153	  const formatted = date.toLocaleDateString("en-US", {
154	    year: "numeric",
155	    month: "long",
156	    day: "numeric",
157	  });
158	
159	  return (
160	    <div
161	      ref={ref}
162	      className="card relative overflow-hidden border border-white/[0.06]"
163	    >
164	      {/* Timeline dot + date row */}
165	      <div className="flex items-center gap-3 px-5 pt-5">
166	        <span className="h-2.5 w-2.5 shrink-0 rounded-full bg-brand-500" />
167	        <span className="text-xs text-slate-500">{formatted}</span>
168	        {!entry.seen && (
169	          <span className="inline-flex items-center rounded-full border border-brand-400/40 bg-brand-500/15 px-2 py-0.5 text-[10px] font-semibold text-brand-300">
170	            New
171	          </span>
172	        )}
173	        {entry.serviceTypes.length > 0 && (
174	          <div className="ml-auto flex gap-1.5">
175	            {entry.serviceTypes.map((t) => (
176	              <span
177	                key={t}
178	                className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
179	              >
180	                {t}
181	              </span>
182	            ))}
183	          </div>
184	        )}
185	      </div>
186	
187	      {/* Title */}
188	      <h3 className="mt-3 px-5 text-base font-bold text-white">
189	        {entry.title}
190	      </h3>
191	
192	      {/* Body */}
193	      <div className="mt-2 px-5 pb-5">
194	        {entry.gameFamilies.length > 0 && (
195	          <div className="mb-4">
196	            {entry.gameFamilies.length > 1 && (
197	              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
198	                Games covered in this update
199	              </p>
200	            )}
201	            <div className={`grid gap-2 ${entry.gameFamilies.length === 1 ? "grid-cols-3 sm:grid-cols-4" : "grid-cols-4 sm:grid-cols-6"}`}>
202	              {entry.gameFamilies.map((g) => (
203	                <div key={g} className="overflow-hidden rounded-lg border border-white/10">
204	                  <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
205	                  <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
206	                    {GAME_DISPLAY[g as GameFamily]?.name ?? g}
207	                  </p>
208	                </div>
209	              ))}
210	            </div>
211	          </div>
212	        )}
213	        <div dangerouslySetInnerHTML={{ __html: renderMarkdown(entry.body) }} />
214	        {entry.screenshotUrl && (
215	          <div className="mt-4">
216	            {/* eslint-disable-next-line @next/next/no-img-element */}
217	            <img
218	              src={entry.screenshotUrl}
219	              alt={`Screenshot for ${entry.title}`}
220	              className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
221	              loading="lazy"
222	            />
223	          </div>
224	        )}
225	      </div>
226	    </div>
227	  );
228	}
