1	import { requireArea } from "@/lib/rbac";
2	import { PageHeader } from "@/components/ui/primitives";
3	import { listAnnouncements } from "@/lib/actions-announcements";
4	import { AnnouncementsAdmin } from "@/components/admin/AnnouncementsAdmin";
5	
6	export const dynamic = "force-dynamic";
7	
8	export default async function AdminAnnouncementsPage() {
