1	"use client";
2	
3	import { useRef, useState } from "react";
4	import { createPortal } from "react-dom";
5	import { useRouter } from "next/navigation";
6	import {
7	  createAnnouncement,
8	  publishAnnouncement,
9	  unpublishAnnouncement,
10	  deleteAnnouncement,
11	} from "@/lib/actions-announcements";
12	import { renderMarkdown } from "@/lib/blog";
13	import { GameCoverTile } from "@/components/customer/GameCoverTile";
14	import { GAME_FAMILIES, GAME_DISPLAY } from "@/lib/games";
15	
16	type Row = {
17	  id: string;
18	  title: string;
19	  body: string;
20	  serviceTypes: string[];
21	  gameFamilies: string[];
22	  screenshotUrl: string | null;
23	  status: string;
24	  publishedAt: string | null;
25	  createdAt: string;
26	  seenCount: number;
27	};
28	
29	/** Minimal shape the full-fidelity modal needs — satisfied by a saved Row
30	 *  or by the in-progress "New announcement" form, so both use one preview. */
31	type PreviewData = {
32	  title: string;
33	  body: string;
34	  serviceTypes: string[];
35	  gameFamilies: string[];
36	  screenshotUrl: string | null;
37	};
38	
39	const SERVICE_OPTIONS = [
40	  { value: "GAME", label: "Game Servers" },
41	  { value: "VPS", label: "VPS" },
42	  { value: "HOSTING", label: "Hosting" },
43	  { value: "MAIL", label: "Mail" },
44	];
45	
46	/**
47	 * Toolbar buttons that insert Markdown syntax at the textarea's cursor/selection,
48	 * rather than a full WYSIWYG editor — the body is stored and rendered as
49	 * Markdown (renderMarkdown, same as blog posts), so this keeps exactly one
50	 * source of truth for formatting instead of a separate rich-text model that
51	 * would need converting back and forth.
52	 */
53	type ToolAction = {
54	  label: string;
55	  icon: string;
56	  /** Wraps the selection (or inserts a placeholder if nothing is selected). */
57	  apply: (selected: string) => { text: string; cursorOffset?: number };
58	};
59	
60	const TOOLS: ToolAction[] = [
61	  { label: "Bold", icon: "B", apply: (s) => ({ text: `**${s || "bold text"}**` }) },
62	  { label: "Italic", icon: "I", apply: (s) => ({ text: `*${s || "italic text"}*` }) },
63	  { label: "Heading", icon: "H", apply: (s) => ({ text: `## ${s || "Heading"}` }) },
64	  { label: "Sub-heading", icon: "H2", apply: (s) => ({ text: `### ${s || "Sub-heading"}` }) },
65	  {
66	    label: "Bullet list",
67	    icon: "•",
68	    apply: (s) => ({ text: (s || "List item").split("\n").map((l) => `- ${l}`).join("\n") }),
69	  },
70	  {
71	    label: "Numbered list",
72	    icon: "1.",
73	    apply: (s) => ({
74	      text: (s || "List item").split("\n").map((l, i) => `${i + 1}. ${l}`).join("\n"),
75	    }),
76	  },
77	  {
78	    label: "Link",
79	    icon: "🔗",
80	    apply: (s) => ({ text: `[${s || "link text"}](https://)`, cursorOffset: s ? undefined : -3 }),
81	  },
82	  {
83	    label: "Image",
84	    icon: "🖼",
85	    apply: (s) => ({ text: `![${s || "description"}](/uploads/announcements/image.png)` }),
86	  },
87	];
88	
89	/** A Markdown body field with a formatting toolbar + Write/Preview tabs. */
90	function MarkdownField({
91	  value,
92	  onChange,
93	  placeholder,
94	}: {
95	  value: string;
96	  onChange: (v: string) => void;
97	  placeholder?: string;
98	}) {
99	  const [tab, setTab] = useState<"write" | "preview">("write");
100	  const ref = useRef<HTMLTextAreaElement>(null);
101	
102	  function runTool(tool: ToolAction) {
103	    const el = ref.current;
104	    if (!el) return;
105	    const start = el.selectionStart ?? value.length;
106	    const end = el.selectionEnd ?? value.length;
107	    const selected = value.slice(start, end);
108	    const { text, cursorOffset } = tool.apply(selected);
109	    const next = value.slice(0, start) + text + value.slice(end);
110	    onChange(next);
111	    // Restore focus + a sensible cursor position after the DOM updates.
112	    requestAnimationFrame(() => {
113	      el.focus();
114	      const pos = start + text.length + (cursorOffset ?? 0);
115	      el.setSelectionRange(pos, pos);
116	    });
117	  }
118	
119	  return (
120	    <div className="overflow-hidden rounded-xl border border-white/[0.08]">
121	      <div className="flex items-center justify-between border-b border-white/[0.06] bg-white/[0.02] px-2 py-1.5">
122	        <div className="flex flex-wrap gap-0.5">
123	          {TOOLS.map((tool) => (
124	            <button
125	              key={tool.label}
126	              type="button"
127	              title={tool.label}
128	              onClick={() => runTool(tool)}
129	              disabled={tab === "preview"}
130	              className="rounded-md px-2 py-1 text-xs font-medium text-slate-300 transition-colors hover:bg-white/[0.06] hover:text-white disabled:opacity-30"
131	            >
132	              {tool.icon}
133	            </button>
134	          ))}
135	        </div>
136	        <div className="flex gap-1">
137	          <button
138	            type="button"
139	            onClick={() => setTab("write")}
140	            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
141	              tab === "write" ? "bg-brand-500/20 text-brand-300" : "text-slate-500 hover:text-white"
142	            }`}
143	          >
144	            Write
145	          </button>
146	          <button
147	            type="button"
148	            onClick={() => setTab("preview")}
149	            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
150	              tab === "preview" ? "bg-brand-500/20 text-brand-300" : "text-slate-500 hover:text-white"
151	            }`}
152	          >
153	            Preview
154	          </button>
155	        </div>
156	      </div>
157	      {tab === "write" ? (
158	        <textarea
159	          ref={ref}
160	          className="w-full resize-y border-0 bg-transparent px-3 py-2.5 font-mono text-sm text-white placeholder:text-slate-600 focus:outline-none"
161	          rows={8}
162	          placeholder={placeholder}
163	          value={value}
164	          onChange={(e) => onChange(e.target.value)}
165	          maxLength={10000}
166	        />
167	      ) : (
168	        <div className="min-h-[176px] px-3 py-2.5">
169	          {value.trim() ? (
170	            <div dangerouslySetInnerHTML={{ __html: renderMarkdown(value) }} />
171	          ) : (
172	            <p className="text-sm text-slate-600">Nothing to preview yet.</p>
173	          )}
174	        </div>
175	      )}
176	    </div>
177	  );
178	}
179	
180	const STATUS_DOT: Record<string, string> = {
181	  DRAFT: "bg-amber-400",
182	  PUBLISHED: "bg-emerald-400",
183	};
184	
185	const STATUS_BADGE: Record<string, string> = {
186	  DRAFT: "border-amber-500/40 bg-amber-500/10 text-amber-300",
187	  PUBLISHED: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
188	};
189	
190	export function AnnouncementsAdmin({ rows }: { rows: Row[] }) {
191	  const router = useRouter();
192	  const [title, setTitle] = useState("");
193	  const [body, setBody] = useState("");
194	  const [serviceTypes, setServiceTypes] = useState<string[]>([]);
195	  const [gameFamilies, setGameFamilies] = useState<string[]>([]);
196	  const [screenshotUrl, setScreenshotUrl] = useState("");
197	  const [busy, setBusy] = useState(false);
198	  const [err, setErr] = useState("");
199	  const [previewRow, setPreviewRow] = useState<PreviewData | null>(null);
200	
201	  function toggleService(val: string) {
202	    setServiceTypes((prev) =>
203	      prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val],
204	    );
205	    if (val === "GAME") setGameFamilies([]);
206	  }
207	
208	  function toggleGame(val: string) {
209	    setGameFamilies((prev) =>
210	      prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val],
211	    );
212	  }
213	
214	  async function submit() {
215	    setErr("");
216	    setBusy(true);
217	    const res = await createAnnouncement({
218	      title,
219	      body,
220	      serviceTypes,
221	      gameFamilies,
222	      screenshotUrl: screenshotUrl || null,
223	    });
224	    setBusy(false);
225	    if (res.error) {
226	      setErr(res.error);
227	      return;
228	    }
229	    setTitle("");
230	    setBody("");
231	    setServiceTypes([]);
232	    setGameFamilies([]);
233	    setScreenshotUrl("");
234	    router.refresh();
235	  }
236	
237	  async function doPublish(id: string) {
238	    await publishAnnouncement(id);
239	    router.refresh();
240	  }
241	
242	  async function doUnpublish(id: string) {
243	    await unpublishAnnouncement(id);
244	    router.refresh();
245	  }
246	
247	  async function doDelete(id: string) {
248	    if (!confirm("Delete this announcement permanently?")) return;
249	    await deleteAnnouncement(id);
250	    router.refresh();
251	  }
252	
253	  return (
254	    <div className="space-y-6">
255	      {/* Create form */}
256	      <div className="card space-y-4">
257	        <p className="text-sm font-semibold text-white">New announcement</p>
258	
259	        <input
260	          className="input"
261	          placeholder="Title (e.g. New backup system, Game server mods)"
262	          value={title}
263	          onChange={(e) => setTitle(e.target.value)}
264	          maxLength={200}
265	        />
266	
267	        <MarkdownField
268	          value={body}
269	          onChange={setBody}
270	          placeholder="Write the update — use the toolbar above for bold, headings, lists, links and images."
271	        />
272	
273	        <div className="flex flex-wrap items-center gap-4">
274	          <span className="text-xs font-medium text-slate-400">
275	            Service types (empty = shown to all):
276	          </span>
277	          {SERVICE_OPTIONS.map((opt) => (
278	            <label
279	              key={opt.value}
280	              className="flex items-center gap-1.5 text-sm text-slate-300"
281	            >
282	              <input
283	                type="checkbox"
284	                checked={serviceTypes.includes(opt.value)}
285	                onChange={() => toggleService(opt.value)}
286	                className="accent-brand-500"
287	              />
288	              {opt.label}
289	            </label>
290	          ))}
291	        </div>
292	
293	        {serviceTypes.includes("GAME") && (
294	          <div className="rounded-xl border border-white/[0.06] bg-black/20 p-3">
295	            <p className="mb-2 text-xs font-medium text-slate-400">
296	              Games this update covers (optional — leave empty for a general game-server update). Pick multiple for a batch update; each gets its own cover in the customer feed.
297	            </p>
298	            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8">
299	              {GAME_FAMILIES.map((family) => {
300	                const selected = gameFamilies.includes(family);
301	                return (
302	                  <button
303	                    key={family}
304	                    type="button"
305	                    onClick={() => toggleGame(family)}
306	                    className={`group relative overflow-hidden rounded-lg border transition-colors ${
307	                      selected ? "border-brand-400/70" : "border-white/[0.08] hover:border-white/20"
308	                    }`}
309	                  >
310	                    <GameCoverTile family={family} name={GAME_DISPLAY[family].name} />
311	                    <span className="absolute inset-x-0 bottom-0 truncate bg-black/60 px-1 py-0.5 text-[9px] font-medium text-white">
312	                      {GAME_DISPLAY[family].name}
313	                    </span>
314	                    {selected && (
315	                      <span className="absolute right-1 top-1 flex h-4 w-4 items-center justify-center rounded-full bg-brand-500 text-[9px] text-white">
316	                        ✓
317	                      </span>
318	                    )}
319	                  </button>
320	                );
321	              })}
322	            </div>
323	          </div>
324	        )}
325	
326	        <input
327	          className="input text-sm"
328	          placeholder="Screenshot path (optional, e.g. /uploads/announcements/screenshot.png)"
329	          value={screenshotUrl}
330	          onChange={(e) => setScreenshotUrl(e.target.value)}
331	        />
332	
333	        <div className="flex items-center gap-3">
334	          <button
335	            className="btn-primary"
336	            onClick={submit}
337	            disabled={busy || !title.trim() || !body.trim()}
338	          >
339	            {busy ? "Creating..." : "Create draft"}
340	          </button>
341	          <button
342	            type="button"
343	            className="text-xs text-slate-400 hover:text-white"
344	            disabled={!title.trim() && !body.trim()}
345	            onClick={() =>
346	              setPreviewRow({
347	                title: title || "Untitled",
348	                body,
349	                serviceTypes,
350	                gameFamilies,
351	                screenshotUrl: screenshotUrl || null,
