1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { requireArea } from "./rbac";
7	import { GAME_FAMILIES, type GameFamily } from "./games";
8	
9	/**
10	 * Update Announcements — service-specific release notes pushed to customers.
11	 *
12	 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
13	 * Customers see a popup on first login after publish and a persistent
14	 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
15	 * announcements for services they actually have; empty = everyone.
16	 *
17	 * Admin actions are area-gated ("platform"). Customer actions self-auth via
18	 * `requireUser()` and only ever touch that user's own rows.
19	 */
20	
21	const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "MAIL"] as const;
22	export type ServiceType = (typeof SERVICE_TYPES)[number];
23	
24	// ---------- Admin ----------
25	
26	export async function listAnnouncements() {
27	  await requireArea("platform");
28	  return db.updateAnnouncement.findMany({
29	    orderBy: { createdAt: "desc" },
30	    take: 200,
31	    include: { _count: { select: { seenBy: true } } },
32	  });
33	}
34	
35	export async function createAnnouncement(input: {
36	  title: string;
37	  body: string;
38	  serviceTypes: string[];
39	  gameFamilies?: string[];
40	  screenshotUrl?: string | null;
41	}): Promise<{ error?: string; ok?: boolean }> {
42	  await requireArea("platform");
43	  const title = String(input.title ?? "").trim();
44	  if (!title) return { error: "Enter a title." };
45	  const body = String(input.body ?? "").trim();
46	  if (!body) return { error: "Enter a body." };
47	
48	  // Validate service types — only allow known values.
49	  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
50	    (SERVICE_TYPES as readonly string[]).includes(t),
51	  );
52	
53	  // Game families only make sense when the update is GAME-scoped. Validate
54	  // against the real game family list so a typo can never silently no-op.
55	  const gameFamilies = serviceTypes.includes("GAME")
56	    ? (input.gameFamilies ?? []).filter((g) => (GAME_FAMILIES as readonly string[]).includes(g))
57	    : [];
58	
59	  // Screenshot must be a relative path, not an external URL.
60	  let screenshotUrl: string | null = null;
61	  if (input.screenshotUrl) {
62	    const u = input.screenshotUrl.trim();
63	    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
64	    screenshotUrl = u || null;
65	  }
66	
67	  await db.updateAnnouncement.create({
68	    data: {
69	      title: title.slice(0, 200),
70	      body: body.slice(0, 10_000),
71	      serviceTypes,
72	      gameFamilies,
73	      screenshotUrl,
74	      status: "DRAFT",
75	    },
76	  });
77	  revalidatePath("/admin/announcements");
78	  return { ok: true };
79	}
80	
81	export async function publishAnnouncement(id: string): Promise<void> {
82	  await requireArea("platform");
83	  await db.updateAnnouncement.update({
84	    where: { id },
85	    data: { status: "PUBLISHED", publishedAt: new Date() },
86	  });
87	  revalidatePath("/admin/announcements");
88	}
89	
90	export async function unpublishAnnouncement(id: string): Promise<void> {
91	  await requireArea("platform");
92	  await db.updateAnnouncement.update({
93	    where: { id },
94	    data: { status: "DRAFT" },
95	  });
96	  revalidatePath("/admin/announcements");
97	}
98	
99	export async function deleteAnnouncement(id: string): Promise<void> {
100	  await requireArea("platform");
101	  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
102	  revalidatePath("/admin/announcements");
103	}
104	
105	// ---------- Customer ----------
106	
107	/** Determine which service types the current user has active services for. */
108	async function getUserServiceTypes(userId: string): Promise<string[]> {
109	  const [servers, hosting] = await Promise.all([
110	    db.server.findFirst({ where: { userId } }),
111	    db.hostingAccount.findFirst({ where: { userId } }),
112	  ]);
113	  const types: string[] = [];
114	  if (servers) {
115	    const hasGame = await db.server.findFirst({
116	      where: { userId, gamePlanId: { not: null } },
117	    });
118	    if (hasGame) types.push("GAME");
119	    const hasVps = await db.server.findFirst({
120	      where: { userId, gamePlanId: null },
121	    });
122	    if (hasVps) types.push("VPS");
123	  }
124	  if (hosting) types.push("HOSTING");
125	  // MAIL: anyone with a hosting account potentially has mail; we keep it
126	  // simple and include MAIL for hosting customers too.
127	  if (hosting) types.push("MAIL");
128	  return types;
129	}
130	
131	/**
132	 * PUBLISHED announcements the current user hasn't seen, filtered by service
133	 * types matching their actual services. An announcement with empty
134	 * serviceTypes[] is shown to everyone.
135	 */
136	export async function getUnseenAnnouncements() {
137	  const user = await requireUser();
138	  const userServices = await getUserServiceTypes(user.id);
139	
140	  const announcements = await db.updateAnnouncement.findMany({
141	    where: {
142	      status: "PUBLISHED",
143	      seenBy: { none: { userId: user.id } },
144	    },
145	    orderBy: { publishedAt: "desc" },
146	  });
147	
148	  // Filter by service type: show if announcement has no serviceTypes (global)
149	  // or if at least one of the user's service types matches.
150	  return announcements.filter(
151	    (a) =>
152	      a.serviceTypes.length === 0 ||
153	      a.serviceTypes.some((t) => userServices.includes(t)),
154	  );
155	}
156	
157	/** Mark an announcement as seen by the current user. Upserts to stay idempotent. */
158	export async function markAnnouncementSeen(announcementId: string): Promise<void> {
159	  const user = await requireUser();
160	  await db.userAnnouncementSeen.upsert({
161	    where: {
162	      userId_announcementId: { userId: user.id, announcementId },
163	    },
164	    create: { userId: user.id, announcementId },
165	    update: {},
166	  });
167	}
168	
169	export type WhatsNewEntry = {
170	  id: string;
171	  title: string;
172	  body: string;
173	  serviceTypes: string[];
174	  gameFamilies: string[];
175	  screenshotUrl: string | null;
176	  publishedAt: string; // ISO string for serialization
177	  seen: boolean;
178	};
179	
180	/**
181	 * All PUBLISHED announcements, optionally filtered by service type, ordered
182	 * by publishedAt desc, with a `seen` boolean flag for the current user.
183	 */
184	export async function getWhatsNew(
185	  serviceFilter?: string,
186	): Promise<WhatsNewEntry[]> {
187	  const user = await requireUser();
188	
189	  const where: Record<string, unknown> = { status: "PUBLISHED" };
190	  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
191	    where.serviceTypes = { has: serviceFilter };
192	  }
193	
194	  const announcements = await db.updateAnnouncement.findMany({
195	    where,
196	    orderBy: { publishedAt: "desc" },
197	    include: {
198	      seenBy: {
199	        where: { userId: user.id },
200	        take: 1,
201	      },
202	    },
203	  });
204	
205	  return announcements.map((a) => ({
206	    id: a.id,
207	    title: a.title,
208	    body: a.body,
209	    serviceTypes: a.serviceTypes,
210	    gameFamilies: a.gameFamilies,
211	    screenshotUrl: a.screenshotUrl,
212	    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
213	    seen: a.seenBy.length > 0,
214	  }));
215	}
